  let seed = 7;
  while (bx < W) {
    const bw = 60 + (seed * 37) % 90;
    const bh = 60 + (seed * 53) % 190;
    ctx.fillRect(bx, H * 0.66 - bh, bw, bh + 40);
    bx += bw + 8; seed++;
  }
  // sea strip
  ctx.fillStyle = 'rgba(38,120,140,0.85)';
  ctx.fillRect(0, H * 0.78, W, H * 0.05);

  // Title
  ctx.textAlign = 'center';
